 NSDictionary *sizes=self.restore?self.inspection[@"manifest"][@"bytesByCategory"]:self.estimate[@"bytesByCategory"];unsigned long long bytes=0;for(NSString *key in self.selected)bytes+=[sizes[key] unsignedLongLongValue];
