}
- (void)scanSizes{self.scanning=YES;[self updateSummary];__weak typeof(self) weak=self;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSError *error=nil;NSDictionary *estimate=DXBackupEstimate(NSHomeDirectory(),[NSSet setWithArray:[DXBackupCategories() valueForKey:@"id"]],&error);dispatch_async(dispatch_get_main_queue(),^{weak.scanning=NO;weak.estimate=estimate;if(error&&!weak.busy)weak.status.text=error.localizedDescription;[weak updateSummary];[weak.tableView reloadData];});});}
- (void)changeMode:(UISegmentedControl *)control{if(self.busy){control.selectedSegmentIndex=self.restore?1:0;return;}self.restore=control.selectedSegmentIndex==1;self.progressView.hidden=YES;self.status.text=self.restore?@"选择备份文件，校验后选择要恢复的分类。":@"压缩前大小，不含设备凭据体积；压缩后文件大小和耗时会因内容、设备性能而变化。";[self updateSummary];[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 3;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?DXBackupCategories().count:s==1?(self.restore?1:3):1;}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return @[@"数据分类",self.restore?@"备份文件":@"加密与凭据",@"备份历史"][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{
 if(s==0)return self.restore?@"合并恢复所选分类，同名文件会被覆盖。恢复前保留原文件；重启 App 后，在会话与工具加载前执行。外部目录授权需重新选择。":@"显示压缩前数据大小，不含可选密钥及清单等开销。不包含 Linux 环境、构建缓存、设备配对与外部目录授权。预计耗时仅供参考。";
 if(s==1)return @"密码不会保存。忘记密码无法恢复；包含 API 密钥或 MCP 凭据时必须加密。未勾选凭据时仅保存配置，换设备后需重新填写密钥。";return nil;
}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{
 if(i.section==0){NSDictionary *c=DXBackupCategories()[i.row];BOOL available=!self.restore||!self.inspection||[self.inspection[@"manifest"][@"categories"] containsObject:c[@"id"]];NSDictionary *sizes=self.restore?self.inspection[@"manifest"][@"bytesByCategory"]:self.estimate[@"bytesByCategory"];NSString *size=sizes?[NSByteCountFormatter stringFromByteCount:[sizes[c[@"id"]] longLongValue] countStyle:NSByteCountFormatterCountStyleFile]:self.restore?@"—":self.scanning?@"统计中…":@"—";UITableViewCell *cell=AICell([NSString stringWithFormat:@"%@ · %@",c[@"name"],size],available?c[@"detail"]:@"该备份未包含此分类",@"archivebox");cell.accessoryType=[self.selected containsObject:c[@"id"]]&&available?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;cell.textLabel.enabled=available;cell.accessibilityIdentifier=[@"backup.category." stringByAppendingString:c[@"id"]];return cell;}
