 if(self.restore){UITableViewCell *c=AICell(@"选择备份文件",self.inspection?[NSString stringWithFormat:@"已校验 · %@ 个文件",@([self.inspection[@"manifest"][@"files"] count])]:@"从“文件”打开 .dylixbak",@"doc.badge.arrow.up");c.accessibilityIdentifier=@"backup.choose";return c;}
